+export function formatBuilderLoopDecisionLabel(input) {
+  switch (input) {
+    case 'approve':
+      return 'Approved';
+    case 'reject':
+      return 'Rejected';
+    case 'request_changes':
+      return 'Changes requested';
+    default:
+      return 'Unknown decision';
+  }
+}
